with d as (select '{"lang":{"id":"java","name":"Java","mono":"Java","color":"#E76F00","accent":"#5382A1","description":"Banyak dipakai untuk aplikasi Android dan sistem perusahaan. Aturannya lebih ketat.","position":1},"units":[{"id":11,"title":"Pengenalan Pemrograman","position":0},{"id":12,"title":"Variabel dan Tipe Data","position":1},{"id":13,"title":"Percabangan","position":2},{"id":14,"title":"Perulangan","position":3}],"lessons":[{"id":1101,"unit_id":11,"title":"Apa itu program?","type":"mc","duration_min":4,"xp":15,"published":true,"position":0,"material":{"intro":"Program adalah sekumpulan perintah yang ditulis agar komputer mengerjakan sesuatu. Di unit ini perintahnya ditulis dengan bahasa Java.","points":[["Komputer hanya mengikuti perintah","Perintah harus jelas dan berurutan, komputer tidak bisa menebak maksud kita."],["Tentang Java","Java banyak dipakai untuk aplikasi Android, server, dan sistem perusahaan."],["Struktur program Java","Kode ditulis di dalam class, dan program mulai berjalan dari method main."]],"code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Halo, Sinau!\");\n    }\n}\n// output: Halo, Sinau!","tip":"Untuk sekarang, cukup hafalkan kerangka class dan main. Kode latihan selalu ditulis di dalam main."}},{"id":1102,"unit_id":11,"title":"Algoritma dan flowchart","type":"order","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Algoritma adalah langkah-langkah logis untuk menyelesaikan masalah. Flowchart adalah gambar dari algoritma tersebut.","points":[["Ciri algoritma","Ada input dan output, langkahnya jelas, dan pasti selesai."],["Oval","Mulai atau selesai."],["Jajar genjang","Input atau output data."],["Persegi panjang","Proses atau perhitungan."],["Belah ketupat","Keputusan atau percabangan (ya/tidak)."]],"tip":"Tulis algoritmanya dulu dengan bahasa sehari-hari, baru ubah menjadi kode."}},{"id":1103,"unit_id":11,"title":"Program pertamamu","type":"mc","duration_min":5,"xp":15,"published":true,"position":2,"material":{"intro":"Untuk menampilkan sesuatu ke layar, Java memakai System.out.println().","points":[["println","Menampilkan teks lalu pindah ke baris baru."],["print","Menampilkan teks tanpa pindah baris."],["Titik koma","Setiap perintah di Java diakhiri tanda titik koma (;)."],["Teks memakai tanda kutip","\"Halo\" adalah teks, sedangkan 2 + 3 dihitung menjadi 5."]],"code":"System.out.println(\"Halo, dunia!\");\nSystem.out.println(2 + 3);\n// output:\n// Halo, dunia!\n// 5","tip":"Huruf besar dan kecil berpengaruh di Java: System harus diawali huruf S besar."}},{"id":1104,"unit_id":11,"title":"Komentar dan error","type":"mc","duration_min":5,"xp":15,"published":true,"position":3,"material":{"intro":"Komentar adalah catatan di dalam kode yang tidak dijalankan. Error adalah kesalahan yang membuat program gagal dikompilasi atau dijalankan.","points":[["Komentar satu baris","Diawali tanda //."],["Komentar banyak baris","Diapit /* dan */."],["Error kompilasi","Penulisan salah, misalnya lupa titik koma atau kurung kurawal tidak ditutup."],["Baca pesan error","Pesan error menyebut baris dan jenis kesalahannya, misalnya \"'';'' expected\"."]],"code":"// ini komentar\n/* ini juga komentar\n   beberapa baris */\nSystem.out.println(\"Halo\")   // error: '';'' expected","tip":"Kurung kurawal { } harus selalu berpasangan. Rapikan indentasi agar mudah dicek."}},{"id":1201,"unit_id":12,"title":"Variabel","type":"mc","duration_min":5,"xp":15,"published":true,"position":0,"material":{"intro":"Variabel adalah tempat menyimpan nilai. Di Java, setiap variabel harus ditulis tipe datanya.","points":[["Deklarasi","Tulis tipe, nama, lalu nilainya. Contoh: int umur = 19;"],["Nilai bisa diganti","umur = 20; mengganti isi variabel. Tipe tidak ditulis ulang."],["Aturan nama","Tidak diawali angka dan tanpa spasi. Biasanya memakai camelCase, misalnya namaLengkap."]],"code":"String nama = \"Zidney\";\nint umur = 19;\numur = 20;\nSystem.out.println(nama + \" \" + umur);\n// output: Zidney 20","tip":"Tanda + dipakai untuk menggabungkan teks dengan nilai lain."}},{"id":1202,"unit_id":12,"title":"Tipe data","type":"mc","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Java memeriksa tipe data dengan ketat. Nilai harus sesuai dengan tipe variabelnya.","points":[["int","Bilangan bulat, contoh: 20."],["double","Bilangan desimal, contoh: 3.14."],["String","Teks di antara tanda kutip ganda, contoh: \"Sinau\"."],["boolean","Nilai logika: true atau false."],["char","Satu karakter di antara kutip tunggal, contoh: ''A''."]],"code":"int umur = 20;\ndouble ipk = 3.75;\nString nama = \"Sinau\";\nboolean aktif = true;\nchar nilai = ''A'';","tip":"String diawali huruf S besar, sedangkan int, double, boolean, dan char ditulis huruf kecil."}},{"id":1203,"unit_id":12,"title":"Input dan output","type":"order","duration_min":6,"xp":15,"published":true,"position":2,"material":{"intro":"Untuk membaca input dari keyboard, Java memakai class Scanner.","points":[["Import","Tulis import java.util.Scanner; di bagian paling atas."],["Buat Scanner","Scanner input = new Scanner(System.in);"],["Membaca data","nextLine() untuk teks, nextInt() untuk bilangan bulat, nextDouble() untuk desimal."]],"code":"import java.util.Scanner;\n\nScanner input = new Scanner(System.in);\nSystem.out.print(\"Nama kamu: \");\nString nama = input.nextLine();\nSystem.out.print(\"Umur: \");\nint umur = input.nextInt();\nSystem.out.println(\"Halo \" + nama + \", tahun depan \" + (umur + 1));","tip":"Pakai tanda kurung saat menghitung di dalam teks: \"Umur \" + (umur + 1)."}},{"id":1204,"unit_id":12,"title":"Operator aritmatika","type":"mc","duration_min":5,"xp":15,"published":true,"position":3,"material":{"intro":"Operator aritmatika dipakai untuk menghitung, seperti kalkulator.","points":[["+  -  *  /","Tambah, kurang, kali, dan bagi."],["Pembagian int","Jika kedua angka int, hasil / dibulatkan ke bawah: 7 / 2 = 3."],["%","Sisa bagi (modulo), sering dipakai untuk cek ganjil atau genap."],["Pangkat","Memakai Math.pow(2, 3) yang hasilnya 8.0."]],"code":"System.out.println(7 / 2);    // 3\nSystem.out.println(7.0 / 2);  // 3.5\nSystem.out.println(7 % 2);    // 1\nSystem.out.println(Math.pow(2, 3)); // 8.0","tip":"Kalau ingin hasil desimal, pastikan salah satu angkanya bertipe double, misalnya 7.0 / 2."}},{"id":1301,"unit_id":13,"title":"Perbandingan dan logika","type":"result","duration_min":5,"xp":15,"published":true,"position":0,"material":{"intro":"Kondisi adalah pernyataan yang hasilnya true atau false. Kondisi dipakai di percabangan dan perulangan.","points":[["Operator perbandingan","== sama dengan, != tidak sama, >, <, >=, <=."],["&& (dan)","true jika kedua kondisi benar."],["|| (atau)","true jika minimal salah satu kondisi benar."],["! (bukan)","Membalik nilai: !true menjadi false."]],"code":"int nilai = 80;\nSystem.out.println(nilai >= 75);               // true\nSystem.out.println(nilai > 90 || nilai == 80); // true\nSystem.out.println(nilai > 70 && nilai < 75);  // false","tip":"Jangan tertukar: = untuk mengisi variabel, == untuk membandingkan."}},{"id":1302,"unit_id":13,"title":"If dan else","type":"mc","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Percabangan membuat program memilih jalan berdasarkan kondisi.","points":[["if","Blok di dalam kurung kurawal dijalankan jika kondisi true."],["else","Dijalankan jika kondisi if false."],["Kurung ()","Kondisi wajib ditulis di dalam tanda kurung."],["Kurung kurawal {}","Menandai awal dan akhir blok perintah."]],"code":"int nilai = 70;\nif (nilai >= 75) {\n    System.out.println(\"Lulus\");\n} else {\n    System.out.println(\"Belum lulus\");\n}\n// output: Belum lulus","tip":"Biasakan selalu memakai kurung kurawal, walaupun isi blok hanya satu baris."}},{"id":1303,"unit_id":13,"title":"Else if: banyak pilihan","type":"mc","duration_min":6,"xp":15,"published":true,"position":2,"material":{"intro":"Kalau pilihannya lebih dari dua, gunakan else if.","points":[["if","Kondisi pertama yang dicek."],["else if","Dicek jika kondisi sebelumnya false. Boleh lebih dari satu."],["else","Dijalankan jika semua kondisi false."],["Urutan penting","Begitu satu kondisi true, sisanya dilewati."]],"code":"int nilai = 75;\nif (nilai >= 85) {\n    System.out.println(\"A\");\n} else if (nilai >= 70) {\n    System.out.println(\"B\");\n} else {\n    System.out.println(\"C\");\n}\n// output: B","tip":"Susun kondisi dari yang paling ketat (nilai terbesar) ke yang paling longgar."}},{"id":1304,"unit_id":13,"title":"Percabangan bersarang","type":"mc","duration_min":6,"xp":15,"published":true,"position":3,"material":{"intro":"Percabangan bersarang adalah if di dalam if. Dipakai jika keputusan kedua bergantung pada keputusan pertama.","points":[["If luar","Dicek lebih dulu."],["If dalam","Hanya dicek jika if luar bernilai true."],["Perhatikan kurung kurawal","Pasangan { } menunjukkan blok mana milik if yang mana."]],"code":"boolean hadir = true;\nint nilai = 80;\nif (hadir) {\n    if (nilai >= 75) {\n        System.out.println(\"Lulus\");\n    } else {\n        System.out.println(\"Remedial\");\n    }\n} else {\n    System.out.println(\"Tidak boleh ujian\");\n}","tip":"Jika bersarang terlalu dalam, sederhanakan dengan &&, misalnya: if (hadir && nilai >= 75)."}},{"id":1401,"unit_id":14,"title":"Perulangan for","type":"mc","duration_min":6,"xp":15,"published":true,"position":0,"material":{"intro":"Perulangan for menjalankan perintah berulang kali sebanyak yang ditentukan.","points":[["Tiga bagian","for (nilai awal; kondisi; perubahan) { ... }"],["i++","Menambah nilai i sebesar 1 setiap putaran."],["Kondisi","Perulangan berjalan selama kondisinya true."]],"code":"for (int i = 1; i <= 3; i++) {\n    System.out.println(\"Putaran ke-\" + i);\n}\n// Putaran ke-1\n// Putaran ke-2\n// Putaran ke-3","tip":"Pakai for jika jumlah pengulangannya sudah diketahui."}},{"id":1402,"unit_id":14,"title":"Perulangan while","type":"mc","duration_min":6,"xp":15,"published":true,"position":1,"material":{"intro":"Perulangan while menjalankan perintah selama kondisinya masih true.","points":[["Kondisi dicek setiap putaran","Jika false, perulangan berhenti."],["Ubah nilai di dalam loop","Kalau tidak, kondisi tidak pernah false (infinite loop)."],["Kapan pakai while?","Saat jumlah pengulangan belum pasti."]],"code":"int n = 3;\nwhile (n > 0) {\n    System.out.println(n);\n    n--;\n}\nSystem.out.println(\"Selesai!\");","tip":"n-- sama dengan n = n - 1."}},{"id":1403,"unit_id":14,"title":"Break dan continue","type":"mc","duration_min":5,"xp":15,"published":true,"position":2,"material":{"intro":"break dan continue mengatur jalannya perulangan dari dalam.","points":[["break","Menghentikan perulangan saat itu juga."],["continue","Melewati sisa perintah pada putaran ini, lalu lanjut ke putaran berikutnya."],["Biasanya dipakai dengan if","Contoh: hentikan perulangan jika data yang dicari sudah ketemu."]],"code":"for (int i = 1; i <= 5; i++) {\n    if (i == 3) continue;\n    if (i == 5) break;\n    System.out.println(i);\n}\n// output: 1 2 4","tip":"break keluar dari perulangan, continue hanya melompati satu putaran."}},{"id":1404,"unit_id":14,"title":"Studi kasus perulangan","type":"order","duration_min":7,"xp":15,"published":true,"position":3,"material":{"intro":"Mari gabungkan input, percabangan, dan perulangan dalam satu program kecil.","points":[["Kasus","Hitung rata-rata nilai beberapa orang, lalu tentukan lulus atau tidak."],["Langkah 1","Siapkan Scanner dan variabel total = 0."],["Langkah 2","Ulangi input nilai sebanyak jumlah orang sambil menambah total."],["Langkah 3","Hitung rata-rata (pakai double), lalu cek dengan if."]],"code":"Scanner sc = new Scanner(System.in);\nint jumlah = 3, total = 0;\nfor (int i = 0; i < jumlah; i++) {\n    total += sc.nextInt();\n}\ndouble rata = (double) total / jumlah;\nif (rata >= 75) {\n    System.out.println(\"Rata-rata \" + rata + \" lulus\");\n} else {\n    System.out.println(\"Rata-rata \" + rata + \" belum lulus\");\n}","tip":"(double) total mengubah total menjadi desimal, supaya hasil bagi tidak dibulatkan."}}],"questions":[{"lesson_id":1101,"position":0,"type":"mc","prompt":"Apa yang dimaksud dengan program?","options":{"opts":["Perangkat keras komputer","Sekumpulan perintah agar komputer mengerjakan sesuatu","Gambar di layar","Koneksi internet"]},"answer":1,"explanation":"Program adalah kumpulan perintah yang dijalankan komputer secara berurutan."},{"lesson_id":1101,"position":1,"type":"mc","prompt":"Di Java, program mulai dijalankan dari method …","options":{"opts":["main","start","run","print"]},"answer":0,"explanation":"Java selalu memulai program dari method public static void main(String[] args)."},{"lesson_id":1101,"position":2,"type":"mc","prompt":"Manakah yang termasuk bahasa pemrograman?","options":{"opts":["Microsoft Word","Java","Windows","Google Chrome"]},"answer":1,"explanation":"Java adalah bahasa pemrograman. Yang lain adalah aplikasi atau sistem operasi."},{"lesson_id":1102,"position":0,"type":"mc","prompt":"Simbol flowchart untuk keputusan (ya/tidak) adalah …","options":{"opts":["Oval","Persegi panjang","Belah ketupat","Jajar genjang"]},"answer":2,"explanation":"Belah ketupat dipakai untuk kondisi yang jawabannya ya atau tidak."},{"lesson_id":1102,"position":1,"type":"mc","prompt":"Simbol oval pada flowchart menandakan …","options":{"opts":["Proses","Mulai atau selesai","Input","Keputusan"]},"answer":1,"explanation":"Oval adalah simbol terminal, yaitu awal dan akhir algoritma."},{"lesson_id":1102,"position":2,"type":"order","prompt":"Susun algoritma menghitung luas persegi panjang","options":{"blocks":["Mulai","Masukkan panjang dan lebar","luas = panjang × lebar","Tampilkan luas","Selesai"],"pool":[2,4,0,3,1]},"answer":[0,1,2,3,4],"explanation":"Mulai → input → proses → output → selesai."},{"lesson_id":1103,"position":0,"type":"mc","prompt":"Perintah untuk menampilkan teks lalu pindah baris di Java adalah …","options":{"opts":["print()","System.out.println()","echo","console.log()"]},"answer":1,"explanation":"System.out.println() menampilkan teks lalu pindah ke baris berikutnya."},{"lesson_id":1103,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"System.out.println(4 + 6);","opts":["4 + 6","10","46","Error"]},"answer":1,"explanation":"Tanpa tanda kutip, Java menghitung 4 + 6 = 10."},{"lesson_id":1103,"position":2,"type":"mc","prompt":"Setiap perintah di Java harus diakhiri dengan tanda …","options":{"opts":["Titik dua (:)","Titik koma (;)","Koma (,)","Tidak perlu tanda"]},"answer":1,"explanation":"Java memakai titik koma sebagai akhir setiap perintah."},{"lesson_id":1104,"position":0,"type":"mc","prompt":"Komentar satu baris di Java diawali dengan …","options":{"opts":["#","//","--","<!--"]},"answer":1,"explanation":"Di Java, komentar satu baris diawali //."},{"lesson_id":1104,"position":1,"type":"mc","prompt":"Mengapa kode berikut error?","options":{"code":"System.out.println(\"Halo\")","opts":["Teksnya terlalu pendek","Tidak ada titik koma di akhir","Harus memakai print","Tanda kutip salah"]},"answer":1,"explanation":"Setiap perintah Java harus diakhiri titik koma."},{"lesson_id":1104,"position":2,"type":"mc","prompt":"Apa yang terjadi pada komentar saat program dijalankan?","options":{"opts":["Ditampilkan ke layar","Diabaikan","Membuat error","Dijalankan dua kali"]},"answer":1,"explanation":"Komentar hanya catatan untuk manusia, Java mengabaikannya."},{"lesson_id":1201,"position":0,"type":"mc","prompt":"Berapa nilai x setelah kode ini dijalankan?","options":{"code":"int x = 5;\nx = x + 3;\nx = x * 2;","opts":["8","10","16","13"]},"answer":2,"explanation":"x = 5 → 8 → 16."},{"lesson_id":1201,"position":1,"type":"mc","prompt":"Manakah nama variabel yang benar di Java?","options":{"opts":["2nilai","nilai akhir","nilaiAkhir","nilai-akhir"]},"answer":2,"explanation":"Nama variabel tidak boleh diawali angka, tidak boleh ada spasi, dan tidak boleh memakai tanda minus."},{"lesson_id":1201,"position":2,"type":"mc","prompt":"Deklarasi variabel yang benar di Java adalah …","options":{"opts":["umur = 19","int umur = 19;","int umur == 19;","var umur: 19"]},"answer":1,"explanation":"Format deklarasi Java: tipe nama = nilai; lalu diakhiri titik koma."},{"lesson_id":1202,"position":0,"type":"mc","prompt":"Tipe data yang cocok untuk nilai 3.14 adalah …","options":{"opts":["int","double","String","boolean"]},"answer":1,"explanation":"Bilangan desimal disimpan dengan tipe double."},{"lesson_id":1202,"position":1,"type":"mc","prompt":"Nilai true dan false termasuk tipe data …","options":{"opts":["int","String","boolean","char"]},"answer":2,"explanation":"true dan false adalah nilai logika bertipe boolean."},{"lesson_id":1202,"position":2,"type":"mc","prompt":"Manakah deklarasi yang benar?","options":{"opts":["int nama = \"Budi\";","String nama = \"Budi\";","char nama = \"Budi\";","boolean nama = \"Budi\";"]},"answer":1,"explanation":"Teks lebih dari satu karakter disimpan dengan tipe String."},{"lesson_id":1203,"position":0,"type":"mc","prompt":"Class yang dipakai untuk membaca input keyboard di Java adalah …","options":{"opts":["Input","Scanner","Reader","Keyboard"]},"answer":1,"explanation":"Scanner dari paket java.util dipakai untuk membaca input."},{"lesson_id":1203,"position":1,"type":"mc","prompt":"Method Scanner untuk membaca bilangan bulat adalah …","options":{"opts":["nextLine()","nextInt()","readInt()","getInt()"]},"answer":1,"explanation":"nextInt() membaca bilangan bulat dari input."},{"lesson_id":1203,"position":2,"type":"order","prompt":"Susun program yang membaca dua angka lalu menampilkan jumlahnya","options":{"blocks":["Scanner sc = new Scanner(System.in);","int a = sc.nextInt();","int b = sc.nextInt();","System.out.println(\"Jumlah: \" + (a + b));"],"pool":[2,0,3,1]},"answer":[0,1,2,3],"explanation":"Buat Scanner, baca angka pertama dan kedua, lalu tampilkan jumlahnya."},{"lesson_id":1204,"position":0,"type":"mc","prompt":"Apa hasil dari 10 % 3?","options":{"opts":["3","1","3.33","0"]},"answer":1,"explanation":"10 dibagi 3 hasilnya 3 sisa 1, jadi 10 % 3 = 1."},{"lesson_id":1204,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"System.out.println(9 / 2);","opts":["4.5","4","5","1"]},"answer":1,"explanation":"9 dan 2 bertipe int, jadi hasilnya dibulatkan ke bawah menjadi 4."},{"lesson_id":1204,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"System.out.println(2 + 3 * 4);","opts":["20","14","24","9"]},"answer":1,"explanation":"Perkalian dihitung dulu: 3 × 4 = 12, lalu 2 + 12 = 14."},{"lesson_id":1301,"position":0,"type":"mc","prompt":"Operator \"dan\" di Java ditulis …","options":{"opts":["and","&&","||","&"]},"answer":1,"explanation":"Java memakai && untuk \"dan\" dan || untuk \"atau\"."},{"lesson_id":1301,"position":1,"type":"mc","prompt":"Lengkapi tabel hasil a && b pada baris yang kosong.","options":{"table":{"head":["a","b","a && b"],"rows":[["true","true","true"],["true","false","?"],["false","true","false"],["false","false","false"]]},"opts":["true","false"]},"answer":1,"explanation":"&& hanya true jika keduanya true. Karena b false, hasilnya false."},{"lesson_id":1301,"position":2,"type":"mc","prompt":"Jika x = 5, apa hasil dari x > 3 || x > 10?","options":{"opts":["true","false","5","Error"]},"answer":0,"explanation":"x > 3 bernilai true. Dengan ||, cukup satu yang true agar hasilnya true."},{"lesson_id":1302,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"int umur = 17;\nif (umur >= 17) {\n    System.out.println(\"Boleh membuat KTP\");\n} else {\n    System.out.println(\"Belum boleh\");\n}","opts":["Boleh membuat KTP","Belum boleh","Keduanya","Error"]},"answer":0,"explanation":"17 >= 17 bernilai true, jadi blok if yang dijalankan."},{"lesson_id":1302,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"int x = 7;\nif (x % 2 == 0) {\n    System.out.println(\"genap\");\n} else {\n    System.out.println(\"ganjil\");\n}","opts":["genap","ganjil","7","Error"]},"answer":1,"explanation":"7 % 2 = 1, bukan 0, jadi blok else yang dijalankan."},{"lesson_id":1302,"position":2,"type":"mc","prompt":"Mengapa kode berikut error?","options":{"code":"if 5 > 3 {\n    System.out.println(\"benar\");\n}","opts":["Angkanya salah","Kondisi harus ditulis di dalam tanda kurung ()","println salah tulis","Harus memakai else"]},"answer":1,"explanation":"Di Java, kondisi if wajib diapit tanda kurung: if (5 > 3)."},{"lesson_id":1303,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"int nilai = 60;\nif (nilai >= 85) {\n    System.out.println(\"A\");\n} else if (nilai >= 70) {\n    System.out.println(\"B\");\n} else {\n    System.out.println(\"C\");\n}","opts":["A","B","C","Tidak ada output"]},"answer":2,"explanation":"60 tidak memenuhi >= 85 maupun >= 70, jadi blok else yang dijalankan."},{"lesson_id":1303,"position":1,"type":"mc","prompt":"Berapa blok else if yang boleh dipakai dalam satu percabangan?","options":{"opts":["Hanya satu","Maksimal dua","Boleh lebih dari satu","Tidak boleh ada"]},"answer":2,"explanation":"else if boleh dipakai sebanyak yang dibutuhkan."},{"lesson_id":1303,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"int suhu = 35;\nif (suhu > 30) {\n    System.out.println(\"Panas\");\n} else if (suhu > 20) {\n    System.out.println(\"Hangat\");\n}","opts":["Panas","Hangat","Panas dan Hangat","Tidak ada output"]},"answer":0,"explanation":"Kondisi pertama sudah true, jadi else if dilewati."},{"lesson_id":1304,"position":0,"type":"mc","prompt":"Apa output kode di materi jika hadir = true dan nilai = 60?","options":{"opts":["Lulus","Remedial","Tidak boleh ujian","Error"]},"answer":1,"explanation":"hadir true, lalu nilai 60 < 75, jadi blok else bagian dalam: Remedial."},{"lesson_id":1304,"position":1,"type":"mc","prompt":"Apa output kode di materi jika hadir = false dan nilai = 90?","options":{"opts":["Lulus","Remedial","Tidak boleh ujian","Tidak ada output"]},"answer":2,"explanation":"If luar sudah false, jadi if dalam tidak dicek sama sekali."},{"lesson_id":1304,"position":2,"type":"mc","prompt":"Kondisi \"hadir dan nilai minimal 75\" bisa ditulis dalam satu if sebagai …","options":{"opts":["if (hadir || nilai >= 75)","if (hadir && nilai >= 75)","if (!hadir)","if (nilai >= 75 else hadir)"]},"answer":1,"explanation":"&& memastikan kedua kondisi harus benar."},{"lesson_id":1401,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for (int i = 0; i < 3; i++) {\n    System.out.println(i);\n}","opts":["1 2 3","0 1 2","0 1 2 3","3"]},"answer":1,"explanation":"i mulai dari 0 dan berhenti sebelum 3, jadi 0, 1, 2."},{"lesson_id":1401,"position":1,"type":"mc","prompt":"Berapa kali kata \"Halo\" dicetak?","options":{"code":"for (int i = 2; i < 7; i++) {\n    System.out.println(\"Halo\");\n}","opts":["5","6","7","2"]},"answer":0,"explanation":"i bernilai 2, 3, 4, 5, 6, yaitu 5 kali."},{"lesson_id":1401,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"int total = 0;\nfor (int i = 1; i <= 4; i++) {\n    total = total + i;\n}\nSystem.out.println(total);","opts":["10","15","4","5"]},"answer":0,"explanation":"1 + 2 + 3 + 4 = 10."},{"lesson_id":1402,"position":0,"type":"mc","prompt":"Berapa kali kata \"Halo\" dicetak?","options":{"code":"int n = 0;\nwhile (n < 4) {\n    System.out.println(\"Halo\");\n    n++;\n}","opts":["3","4","5","Tak terbatas"]},"answer":1,"explanation":"n bernilai 0, 1, 2, 3 (4 kali), lalu berhenti saat n = 4."},{"lesson_id":1402,"position":1,"type":"mc","prompt":"Apa yang terjadi pada kode berikut?","options":{"code":"int x = 1;\nwhile (x > 0) {\n    System.out.println(x);\n}","opts":["Mencetak 1 sekali","Tidak mencetak apa-apa","Berjalan terus tanpa henti","Error"]},"answer":2,"explanation":"Nilai x tidak pernah berubah, jadi kondisi selalu true (infinite loop)."},{"lesson_id":1402,"position":2,"type":"mc","prompt":"Perulangan yang cocok ketika jumlah pengulangannya belum diketahui adalah …","options":{"opts":["for","while","if","switch"]},"answer":1,"explanation":"while berulang selama kondisinya true, jadi cocok saat jumlah putaran belum pasti."},{"lesson_id":1403,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for (int i = 0; i < 5; i++) {\n    if (i == 2) break;\n    System.out.println(i);\n}","opts":["0 1","0 1 2","0 1 3 4","2"]},"answer":0,"explanation":"Saat i = 2, break menghentikan perulangan, jadi yang tercetak hanya 0 dan 1."},{"lesson_id":1403,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for (int i = 0; i < 4; i++) {\n    if (i == 1) continue;\n    System.out.println(i);\n}","opts":["0 2 3","0 1 2 3","1","0"]},"answer":0,"explanation":"Saat i = 1, continue melewati println, lalu lanjut ke putaran berikutnya."},{"lesson_id":1403,"position":2,"type":"mc","prompt":"Perintah untuk menghentikan perulangan sepenuhnya adalah …","options":{"opts":["continue","stop","break","exit"]},"answer":2,"explanation":"break langsung keluar dari perulangan."},{"lesson_id":1404,"position":0,"type":"mc","prompt":"Jika nilai yang dimasukkan 80, 70, dan 90, berapa nilai rata?","options":{"opts":["70.0","80.0","90.0","240.0"]},"answer":1,"explanation":"(80 + 70 + 90) ÷ 3 = 240 ÷ 3 = 80.0."},{"lesson_id":1404,"position":1,"type":"mc","prompt":"Apa fungsi (double) pada (double) total / jumlah?","options":{"opts":["Menggandakan total","Mengubah total ke desimal agar hasil bagi tidak dibulatkan","Menghapus total","Membuat error"]},"answer":1,"explanation":"Tanpa (double), pembagian dua int akan dibulatkan ke bawah."},{"lesson_id":1404,"position":2,"type":"order","prompt":"Susun program yang mencetak bilangan genap dari 1 sampai 10","options":{"blocks":["for (int i = 1; i <= 10; i++) {","    if (i % 2 == 0) {","        System.out.println(i);","    }","}"],"pool":[2,4,0,3,1]},"answer":[0,1,2,3,4],"explanation":"Ulangi 1 sampai 10, cek apakah habis dibagi 2, cetak bilangannya, lalu tutup kedua blok."}]}'::jsonb as j),
lang as (insert into public.languages (id,name,mono,color,accent,description,position)
  select x.id,x.name,x.mono,x.color,x.accent,x.description,x.position from d, jsonb_to_record(d.j->'lang') as x(id text,name text,mono text,color text,accent text,description text,position smallint) returning id),
un as (insert into public.units (id,language_id,title,position)
  select x.id,(select id from lang),x.title,x.position from d, jsonb_to_recordset(d.j->'units') as x(id bigint,title text,position smallint) returning id),
le as (insert into public.lessons (id,unit_id,title,type,duration_min,xp,published,position,material)
  select x.id,x.unit_id,x.title,x.type,x.duration_min,x.xp,x.published,x.position,x.material from d, jsonb_to_recordset(d.j->'lessons') as x(id bigint,unit_id bigint,title text,type text,duration_min smallint,xp smallint,published boolean,position smallint,material jsonb)
  where x.unit_id in (select id from un) returning id)
insert into public.questions (lesson_id,position,type,prompt,options,answer,explanation)
  select x.lesson_id,x.position,x.type,x.prompt,x.options,x.answer,x.explanation from d, jsonb_to_recordset(d.j->'questions') as x(lesson_id bigint,position smallint,type text,prompt text,options jsonb,answer jsonb,explanation text)
  where x.lesson_id in (select id from le);
